(()=>{const canvas=document.querySelector('#field'),ctx=canvas.getContext('2d'),world=document.querySelector('.world'),reduce=matchMedia('(prefers-reduced-motion: reduce)');let w=0,h=0,stalks=[],pointer={x:-1000,y:-1000},frame;function resize(){w=innerWidth;h=innerHeight;const d=Math.min(devicePixelRatio||1,2);canvas.width=w*d;canvas.height=h*d;ctx.setTransform(d,0,0,d,0,0);stalks=Array.from({length:Math.floor(w/14)},(_,i)=>({x:i*14+Math.random()*10,length:22+Math.random()*58,phase:Math.random()*6}));}function paint(t){ctx.clearRect(0,0,w,h);for(const s of stalks){const dx=s.x-pointer.x,dy=h-pointer.y,dist=Math.hypot(dx,dy);const push=dist<170?Math.sign(dx)*(1-dist/170)*45:0;const sway=reduce.matches?0:Math.sin(t*.0013+s.phase)*7+push;ctx.strokeStyle=s.phase>3?'#f4cc52':'#ffe18a';ctx.lineWidth=1.4;ctx.beginPath();ctx.moveTo(s.x,h);ctx.quadraticCurveTo(s.x+sway*.3,h-s.length*.55,s.x+sway,h-s.length);ctx.stroke();for(let j=0;j<4;j++){const y=h-s.length+j*5,x=s.x+sway*(1-j*.08);ctx.beginPath();ctx.moveTo(x,y+5);ctx.lineTo(x-4,y-1);ctx.moveTo(x,y+5);ctx.lineTo(x+4,y-2);ctx.stroke();}}if(!reduce.matches)frame=requestAnimationFrame(paint);}addEventListener('pointermove',e=>{pointer={x:e.clientX,y:e.clientY};if(!reduce.matches){world.style.setProperty('--px',((e.clientX/w-.5)*-16)+'px');world.style.setProperty('--py',((e.clientY/h-.5)*-12)+'px');}},{passive:true});addEventListener('resize',()=>{resize();if(reduce.matches)paint(0)});reduce.addEventListener('change',()=>{cancelAnimationFrame(frame);paint(0)});resize();paint(0);})();